(2795983, 390217, 55169, '<td valign="top">a little dark for the challenge, I''m afraid</td>', 'a little dark for the challenge, I''m afraid', '2006-09-04 11:58:00.000000', NULL, 1),
(2795986, 390078, 55169, '<td valign="top">I like the title and colors.  I think it could benefit from different lighting and less water on the bud</td>', 'I like the title and colors.  I think it could benefit from different lighting and less water on the bud', '2006-09-04 11:58:53.000000', NULL, 1),
(2795987, 389605, 55169, '<td valign="top">interesting photo, but the pastels are too subtle to avoid it being seen as a black/white picture, imho</td>', 'interesting photo, but the pastels are too subtle to avoid it being seen as a black/white picture, imho', '2006-09-04 11:59:39.000000', NULL, 1),
(2795988, 390518, 62671, '<td valign="top">Thats definately pastel in color.  The fisherman is in the right spot, horizon is in the right spot.  but, something feels wrong and I can''t place it.   Perhaps its because Im used to seeing bright vivid color tones.  Or maybe its the jet streams drawing the eye away?  Maybe the fisherman should be a silhouette.  I''m at a loss on it.   I like it so Im giving you a 7.  The sky looks like someone scribbled it in with sky chalk.</td>', 'Thats definately pastel in color.  The fisherman is in the right spot, horizon is in the right spot.  but, something feels wrong and I can''t place it.   Perhaps its because Im used to seeing bright vivid color tones.  Or maybe its the jet streams drawing the eye away?  Maybe the fisherman should be a silhouette.  I''m at a loss on it.   I like it so Im giving you a 7.  The sky looks like someone scribbled it in with sky chalk.', '2006-09-04 11:59:54.000000', NULL, 1),
(2795990, 390139, 55169, '<td valign="top">architectural details are in the foreground, the longer you look, the more the pastel shading appears</td>', 'architectural details are in the foreground, the longer you look, the more the pastel shading appears', '2006-09-04 12:00:24.000000', NULL, 1),
(2795992, 388617, 55169, '<td valign="top">Cute photo, I was there was a bit more color</td>', 'Cute photo, I was there was a bit more color', '2006-09-04 12:00:45.000000', NULL, 1),
(2795995, 387946, 55169, '<td valign="top">Fuzzy texture, wish the green background was less primary</td>', 'Fuzzy texture, wish the green background was less primary', '2006-09-04 12:01:24.000000', NULL, 1),
