(2798363, 390235, 43774, '<td valign="top">Love the DOF and the softness conveyed here</td>', 'Love the DOF and the softness conveyed here', '2006-09-04 22:44:43.000000', NULL, 1),
(2798367, 390504, 62671, '<td valign="top">I like the concept.   I imagine the colors didn''t show up quite right on the shell.   Its not in focus and the darks are noisy.  I would coil up the necklace so its not running out of the frame.  Use an overhead, diffused light.  Also use a black velvet to absorb more light giving more solid black background.  From the reflection on the pearls It looks like your using 2 light sources of different temperatures.  It could be that one is diffused and one isn''t giving a different color.  Keep on trying!</td>', 'I like the concept.   I imagine the colors didn''t show up quite right on the shell.   Its not in focus and the darks are noisy.  I would coil up the necklace so its not running out of the frame.  Use an overhead, diffused light.  Also use a black velvet to absorb more light giving more solid black background.  From the reflection on the pearls It looks like your using 2 light sources of different temperatures.  It could be that one is diffused and one isn''t giving a different color.  Keep on trying!', '2006-09-04 22:45:02.000000', NULL, 1),
(2798368, 390397, 43774, '<td valign="top">Beautiful clarity, wonderful colours.</td>', 'Beautiful clarity, wonderful colours.', '2006-09-04 22:45:12.000000', NULL, 1),
