(2799110, 390101, 43191, '<td valign="top">There seems to be a bit of noise in the shot. getting rid of that would add to the pastel, soft feel imo.</td>', 'There seems to be a bit of noise in the shot. getting rid of that would add to the pastel, soft feel imo.', '2006-09-05 02:33:06.000000', NULL, 1),
(2799170, 390406, 39349, '<td valign="top">This is a really nice shot. Like the tones and composition of the shot. Sharpness really works well here. Well done. 10 from me.</td>', 'This is a really nice shot. Like the tones and composition of the shot. Sharpness really works well here. Well done. 10 from me.', '2006-09-05 03:00:41.000000', NULL, 1),
(2799175, 388043, 39349, '<td valign="top">WOAH! That fish eye really gets the wide range in there hu? I like the skewed angles here. I think that this shot would benefit with more saturation though to show off the pastels, it seems a bit flat to me.</td>', 'WOAH! That fish eye really gets the wide range in there hu? I like the skewed angles here. I think that this shot would benefit with more saturation though to show off the pastels, it seems a bit flat to me.', '2006-09-05 03:02:01.000000', NULL, 1),
