(2801126, 390408, 51538, '<td valign="top">The complimentary colour in the handle is rather nice.  Good work.</td>', 'The complimentary colour in the handle is rather nice.  Good work.', '2006-09-05 16:55:22.000000', NULL, 1),
(2801127, 390441, 43774, '<td valign="top">A good setup but I feel the lighting could be improved to show the pastel colours better.</td>', 'A good setup but I feel the lighting could be improved to show the pastel colours better.', '2006-09-05 16:55:58.000000', NULL, 1),
(2801128, 388430, 51538, '<td valign="top">That all works very well.  Floats like that are attractive but hard to find in the right location to photograph.  I think you''ve done a fine job.</td>', 'That all works very well.  Floats like that are attractive but hard to find in the right location to photograph.  I think you''ve done a fine job.', '2006-09-05 16:56:12.000000', NULL, 1),
(2801129, 390284, 43774, '<td valign="top">Nice colours in the sky but I feel the sunset is ruined by the wires.</td>', 'Nice colours in the sky but I feel the sunset is ruined by the wires.', '2006-09-05 16:56:23.000000', NULL, 1),
