(2807990, 390530, 10867, '<td valign="top">The flower is very nicely shot and the droplets are pretty, but I feel that the colours, especially the very deep, bright green, are too dark and saturated to be classed as pastel.</td>', 'The flower is very nicely shot and the droplets are pretty, but I feel that the colours, especially the very deep, bright green, are too dark and saturated to be classed as pastel.', '2006-09-06 23:28:58.000000', NULL, 1),
(2808013, 388737, 10867, '<td valign="top">Very nice image, but I can''t quite see how it illustrates the challenge topic.</td>', 'Very nice image, but I can''t quite see how it illustrates the challenge topic.', '2006-09-06 23:34:55.000000', NULL, 1),
