(2808394, 388617, 31596, '<td valign="top">What a fantastic shot.... So young and fresh.</td>', 'What a fantastic shot.... So young and fresh.', '2006-09-07 00:51:37.000000', NULL, 1),
(2808395, 389854, 6519, '<td valign="top">I actually like that far away look, makes a nice change from the usual "smile for the camera" style. However, I don''t care for the Neat Image effect (whether or not it actually happened VIA that program) at all.</td>', 'I actually like that far away look, makes a nice change from the usual "smile for the camera" style. However, I don''t care for the Neat Image effect (whether or not it actually happened VIA that program) at all.', '2006-09-07 00:52:14.000000', NULL, 1),
(2808872, 388617, 53316, '<td valign="top">Yay freckles!</td>', 'Yay freckles!', '2006-09-07 03:22:20.000000', NULL, 1),
(2808928, 388617, 39349, '<td valign="top">JENN? You flirt you...Great shot that meets the challenge well. Only think I think I would change is to have you looking directly into the camera.<br/> <br/>Back again, still love this shot bumping up.</td>', 'JENN? You flirt you...Great shot that meets the challenge well. Only think I think I would change is to have you looking directly into the camera. Back again, still love this shot bumping up.', '2006-09-07 04:14:50.000000', NULL, 1),
(2808930, 387936, 39349, '<td valign="top">Like the angle of the model and the pose is interesting. Bumping up.</td>', 'Like the angle of the model and the pose is interesting. Bumping up.', '2006-09-07 04:15:57.000000', NULL, 1),
(2809328, 390119, 25355, '<td valign="top">They seem rather dull and lifeless with this lighting. In fact, I wouldn''t be surprised if they''re fake flowers.</td>', 'They seem rather dull and lifeless with this lighting. In fact, I wouldn''t be surprised if they''re fake flowers.', '2006-09-07 08:01:07.000000', NULL, 1),
(2809573, 389884, 49963, '<td valign="top">A beautiful shot! I really like how you have the dark and bright variations of colours next to each other.</td>', 'A beautiful shot! I really like how you have the dark and bright variations of colours next to each other.', '2006-09-07 09:52:22.000000', NULL, 1),
