INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2809829, 390072, 62099, '<td valign="top">A tad bit on the dark side</td>', 'A tad bit on the dark side', '2006-09-07 11:01:41.000000', NULL, 1),
(2809839, 390176, 62099, '<td valign="top">I love the luminence of the roses</td>', 'I love the luminence of the roses', '2006-09-07 11:02:21.000000', NULL, 1),
(2809878, 390078, 24454, '<td valign="top">This is lovely!  There are some beautiful photos in this challenge, but so many of them are not pastels.  This one is beautiful, and the soft pastel immediately grabs me.  Good luck.  Definitely one of the best in this challenge.</td>', 'This is lovely!  There are some beautiful photos in this challenge, but so many of them are not pastels.  This one is beautiful, and the soft pastel immediately grabs me.  Good luck.  Definitely one of the best in this challenge.', '2006-09-07 11:11:21.000000', NULL, 1),
(2809883, 390513, 24454, '<td valign="top">Now THIS is a beautiful pastel :)   There are so many photos in this challenge that are lovely, but not pastels.  This makes wonderful use of soft pretty pastel colors.  Good luck!</td>', 'Now THIS is a beautiful pastel :)   There are so many photos in this challenge that are lovely, but not pastels.  This makes wonderful use of soft pretty pastel colors.  Good luck!', '2006-09-07 11:12:39.000000', NULL, 1),
(2809941, 390475, 62099, '<td valign="top">The vertical seems to by off a tad</td>', 'The vertical seems to by off a tad', '2006-09-07 11:29:12.000000', NULL, 1),
(2809951, 390494, 62099, '<td valign="top">Image is not sharp</td>', 'Image is not sharp', '2006-09-07 11:31:35.000000', NULL, 1),
(2809979, 390456, 62099, '<td valign="top">Nice image but the halos around the end of the dock and the last boat are a little distracting to me</td>', 'Nice image but the halos around the end of the dock and the last boat are a little distracting to me', '2006-09-07 11:39:14.000000', NULL, 1),
(2810216, 387899, 30757, '<td valign="top">sooooo beautiful 10</td>', 'sooooo beautiful 10', '2006-09-07 13:06:57.000000', NULL, 1),
(2810217, 390397, 30757, '<td valign="top">wonderful</td>', 'wonderful', '2006-09-07 13:07:54.000000', NULL, 1),
(2810395, 390185, 51424, '<td valign="top">I gave you a seven, but would have loved to see a little more colors so I could have given you a higher score. I do love the pictures</td>', 'I gave you a seven, but would have loved to see a little more colors so I could have given you a higher score. I do love the pictures', '2006-09-07 13:43:35.000000', NULL, 1),
(2810607, 390359, 54843, '<td valign="top">Very nice shot, but I am not really seeing the pastels here.</td>', 'Very nice shot, but I am not really seeing the pastels here.', '2006-09-07 14:39:17.000000', NULL, 1),
(2810653, 390472, 53316, '<td valign="top">Absolutely brilliant!!</td>', 'Absolutely brilliant!!', '2006-09-07 14:49:10.000000', NULL, 1),
(2810681, 387899, 30608, '<td valign="top">WOW!!! This is by far the best flamingo picture I have ever seen!! This is beautiful! I also think I am looking at a ribbon winner here! Great Job in composition and your edits. Good luck! Oh yeah - 10</td>', 'WOW!!! This is by far the best flamingo picture I have ever seen!! This is beautiful! I also think I am looking at a ribbon winner here! Great Job in composition and your edits. Good luck! Oh yeah - 10', '2006-09-07 14:54:22.000000', NULL, 1),
(2810804, 390364, 53316, '<td valign="top">A larger file size (up to 150kb) would help your black background look smother and would show more details. Also, I notice that some of the bottles have some stuff on the cap and that is sort of distracting.  I do like the choice of colors that you made - fits the challenge nicely.</td>', 'A larger file size (up to 150kb) would help your black background look smother and would show more details. Also, I notice that some of the bottles have some stuff on the cap and that is sort of distracting.  I do like the choice of colors that you made - fits the challenge nicely.', '2006-09-07 15:16:38.000000', NULL, 1),
(2810821, 389868, 53316, '<td valign="top">Personally, I do not like the way this makes the bottom lip look.  Regarding the actual quality of the shot, the colors, composition, and focus are so great and I love the shimmery lipstick/gloss.</td>', 'Personally, I do not like the way this makes the bottom lip look.  Regarding the actual quality of the shot, the colors, composition, and focus are so great and I love the shimmery lipstick/gloss.', '2006-09-07 15:22:26.000000', NULL, 1),
(2810834, 390489, 53316, '<td valign="top">Such a gorgeous shot - doesn''t really seem pastel to me but I just wanted to comment that the setup and lighting and overall feel of the photo is absolutely wonderful.</td>', 'Such a gorgeous shot - doesn''t really seem pastel to me but I just wanted to comment that the setup and lighting and overall feel of the photo is absolutely wonderful.', '2006-09-07 15:28:35.000000', NULL, 1),
(2810840, 390400, 53316, '<td valign="top">Great title!</td>', 'Great title!', '2006-09-07 15:29:17.000000', NULL, 1),
(2810926, 388329, 53316, '<td valign="top">Do they make pastel sharpies or was that done in post?  In any case the colors here are so lovely and amazing in how they match up together! I would have perfered a white background and maybe a different angle, but regardless this is a great photo.</td>', 'Do they make pastel sharpies or was that done in post?  In any case the colors here are so lovely and amazing in how they match up together! I would have perfered a white background and maybe a different angle, but regardless this is a great photo.', '2006-09-07 15:54:58.000000', NULL, 1),
(2810928, 390521, 53316, '<td valign="top">I like your title - my first thought was a horse falling but your title made me say - oh of course!</td>', 'I like your title - my first thought was a horse falling but your title made me say - oh of course!', '2006-09-07 15:56:07.000000', NULL, 1),
(2810935, 390266, 38234, '<td valign="top">beautiful and so softly pastel!!  I really like the narrow DOF!</td>', 'beautiful and so softly pastel!!  I really like the narrow DOF!', '2006-09-07 15:57:33.000000', NULL, 1),
(2810937, 390493, 38234, '<td valign="top">gorgeous!!</td>', 'gorgeous!!', '2006-09-07 15:57:44.000000', NULL, 1),
(2810939, 388724, 38234, '<td valign="top">gorgeous sky and pastel colours!</td>', 'gorgeous sky and pastel colours!', '2006-09-07 15:58:23.000000', NULL, 1),
(2810950, 390481, 38234, '<td valign="top">I really like this set up and shot!  I so wished the orange red was pink or another other pastel but alas it is not so I have to vote this lower than the 8 I''d like to give it:-((</td>', 'I really like this set up and shot!  I so wished the orange red was pink or another other pastel but alas it is not so I have to vote this lower than the 8 I''d like to give it:-((', '2006-09-07 16:00:43.000000', NULL, 1),
