(2817320, 390302, 55746, '<td valign="top">Nice image.  I would have liked to see more of the right side of her face - perhaps pullng her hair behind her ear.  Otherwise very beautiful.</td>', 'Nice image.  I would have liked to see more of the right side of her face - perhaps pullng her hair behind her ear.  Otherwise very beautiful.', '2006-09-09 08:57:08.000000', NULL, 1),
(2817323, 387946, 55746, '<td valign="top">I would have liked a little less shallow depth of field in order to see more of the fuzzy detail of the plant.  I do like your composition - very dramatic.</td>', 'I would have liked a little less shallow depth of field in order to see more of the fuzzy detail of the plant.  I do like your composition - very dramatic.', '2006-09-09 08:58:39.000000', NULL, 1),
