(2820981, 390266, 15711, '<td valign="top">It''s like they are pushing up through a velvety green fog.  Interesting and not the usual image. I like it.</td>', 'It''s like they are pushing up through a velvety green fog.  Interesting and not the usual image. I like it.', '2006-09-10 19:02:33.000000', NULL, 1),
(2820985, 390406, 15711, '<td valign="top">Crisp and clear. I guess my idea of pastel must be different than others. I''m wanting very pale with a light background, but the image overall just as a stand alone is simply gorgeous with perfect focus.</td>', 'Crisp and clear. I guess my idea of pastel must be different than others. I''m wanting very pale with a light background, but the image overall just as a stand alone is simply gorgeous with perfect focus.', '2006-09-10 19:04:25.000000', NULL, 1),
(2820988, 390408, 15711, '<td valign="top">To me, this is a dark image of pastel paint. Hard to know how to vote. It''s exquisitely done and the lighting and focus are spot on. Hmmmmmm</td>', 'To me, this is a dark image of pastel paint. Hard to know how to vote. It''s exquisitely done and the lighting and focus are spot on. Hmmmmmm', '2006-09-10 19:04:49.000000', NULL, 1),
